const FEATURES=[
['Epsy_width_rheo','AP width','ms',1000],['Epsy_fast_trough_v_rheo','Fast trough','mV',1],['Epsy_peak_deltav_rheo','Peak delta V','mV',1],['Epsy_peak_v_rheo','Peak V','mV',1],['Epsy_postap_slope_rheo','Post-AP slope','mV/ms',1],['Epsy_threshold_v_rheo','Threshold V','mV',1],['Epsy_trough_t_rheo','Trough time','s',1],['Epsy_trough_v_rheo','Trough V','mV',1],['Epsy_upstroke_downstroke_ratio_rheo','Up/down ratio','',1],['Epsy_ahp_delay_5spike','AHP delay, 5-spike','ms',1000],['Epsy_ahp_delay_ratio_5spike','AHP delay ratio, 5-spike','',1],['Epsy_postap_slope_hero','Post-AP slope, hero','mV/ms',1],['Epsy_trough_t_hero','Trough time, hero','s',1],['Epsy_downstroke_adapt_ratio','Downstroke adapt ratio','',1],['Epsy_peak_v_adapt_ratio','Peak V adapt ratio','',1],['Epsy_threshold_v_adapt_ratio','Threshold adapt ratio','',1],['Epsy_upstroke_adapt_ratio','Upstroke adapt ratio','',1],['Epsy_width_adapt_ratio','Width adapt ratio','',1],['Epsy_threshold_v_short_square','Threshold V, short square','mV',1]
].map(([key,label,unit,mult])=>({key,label,unit,mult}));
const CLASSES=['E1','E2','E3','E4'];
const DEFAULTS={scaleMode:'raw',plotMode:'violin-box-points',statMode:'none',pairCount:3,showN:true,showLegend:false,pointSize:2.2,pointOpacity:.58,jitter:.27,violinWidth:.72,bandwidth:1,boxWidth:.34,whiskerMode:'percentile',fontFamily:'Arial',fontSize:8,axisWidth:.8,tickCount:5,showGrid:false,showUnit:true,figureTitle:'Macaque frozen E1–E4 feature comparison',columns:5,panelWidth:230,panelHeight:210,gapX:12,gapY:18,previewZoom:70,pngScale:2,backgroundColor:'#ffffff',textColor:'#1d252c',colors:{E1:'#F8766D',E2:'#7CAE00',E3:'#00BFC4',E4:'#C77CFF'},activeClasses:{E1:true,E2:true,E3:true,E4:true},featureOrder:FEATURES.map(f=>f.key),selected:FEATURES.map(f=>f.key)};
let state=structuredClone(DEFAULTS), rows=[], omnibus=new Map(), pairwise=[];
const $=id=>document.getElementById(id), NS='http://www.w3.org/2000/svg';

function parseCSV(text){const out=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){field+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(field);field='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(Boolean))out.push(row);row=[];field='';}else field+=c;}if(field||row.length){row.push(field);out.push(row);}const head=out.shift();return out.map(r=>Object.fromEntries(head.map((h,i)=>[h,r[i]??''])))}
async function loadData(){const [d,o,p]=await Promise.all(['data.csv','omnibus.csv','pairwise.csv'].map(x=>fetch(x).then(r=>{if(!r.ok)throw Error(x);return r.text()})));rows=parseCSV(d);rows.forEach(r=>r.E_class=r.E_class.replace(/^C/,'E'));parseCSV(o).forEach(r=>omnibus.set(r.Feature,r));pairwise=parseCSV(p);pairwise.forEach(r=>{r.Group_1=r.Group_1.replace(/^C/,'E');r.Group_2=r.Group_2.replace(/^C/,'E')});$('dataStatus').textContent=`已载入主图同一批 ${rows.length} 个冻结共识细胞 · 19 features · E1–E4`;$('dataStatus').style.color='#9bd8d9';render()}
function svgEl(tag,attrs={},text=''){const e=document.createElementNS(NS,tag);for(const [k,v] of Object.entries(attrs))e.setAttribute(k,v);if(text)e.textContent=text;return e}
function quantile(a,q){const x=[...a].sort((a,b)=>a-b),i=(x.length-1)*q,l=Math.floor(i),f=i-l;return x[l]+(x[l+1]??x[l])*f}
function mean(a){return a.reduce((s,v)=>s+v,0)/a.length}
function sd(a){const m=mean(a);return Math.sqrt(a.reduce((s,v)=>s+(v-m)**2,0)/Math.max(1,a.length-1))}
function hash(s){let h=2166136261;for(const c of s){h^=c.charCodeAt(0);h=Math.imul(h,16777619)}return(h>>>0)/4294967295}
function fmt(v){const a=Math.abs(v);if(a>=100)return v.toFixed(0);if(a>=10)return v.toFixed(1);if(a>=1)return v.toFixed(2);return v.toFixed(2)}
function pFmt(p){p=Number(p);return p<.001?p.toExponential(1):p<.01?p.toFixed(3):p.toFixed(2)}
function values(feature,cls){const key=state.scaleMode==='z'?`z__${feature.key}`:feature.key,m=state.scaleMode==='z'?1:feature.mult;return rows.filter(r=>r.E_class===cls).map(r=>Number(r[key])*m).filter(Number.isFinite)}
function whiskers(a){if(state.whiskerMode==='range')return[Math.min(...a),Math.max(...a)];const q1=quantile(a,.25),q3=quantile(a,.75);if(state.whiskerMode==='iqr'){const d=1.5*(q3-q1);return[Math.max(Math.min(...a),q1-d),Math.min(Math.max(...a),q3+d)]}return[quantile(a,.025),quantile(a,.975)]}
function niceTicks(lo,hi,n){const span=Math.max(1e-12,hi-lo),raw=span/Math.max(1,n-1),pow=10**Math.floor(Math.log10(raw)),u=raw/pow,step=(u<=1?1:u<=2?2:u<=5?5:10)*pow,start=Math.ceil(lo/step)*step,out=[];for(let v=start;v<=hi+step*.001;v+=step)out.push(v);return out}
function kde(a,ys,mult){const n=a.length,s=Math.max(sd(a),1e-8),bw=Math.max(1e-8,1.06*s*n**(-.2)*mult);return ys.map(y=>a.reduce((t,v)=>t+Math.exp(-.5*((y-v)/bw)**2),0)/(n*bw))}

function drawPanel(root,feature,x0,y0,w,h,classes){const fs=Number(state.fontSize),sigPairs=state.statMode==='pairwise'?pairwise.filter(r=>r.Feature===feature.key&&Number(r.P_adj_Holm_within_feature)<.05).sort((a,b)=>Number(a.P_adj_Holm_within_feature)-Number(b.P_adj_Holm_within_feature)).slice(0,state.pairCount):[];const top=state.statMode==='pairwise'?36+sigPairs.length*10:34,left=42,right=10,bottom=34,plotW=w-left-right,plotH=h-top-bottom;const groups=classes.map(c=>({c,a:values(feature,c)}));let all=groups.flatMap(g=>g.a),lo=Math.min(...all),hi=Math.max(...all);if(state.scaleMode==='z'){lo=Math.min(lo,-2.5);hi=Math.max(hi,2.5)}let pad=(hi-lo||1)*.08;lo-=pad;hi+=pad;const y=v=>y0+top+(hi-v)/(hi-lo)*plotH,x=i=>x0+left+(i+.5)*plotW/classes.length;
  root.append(svgEl('text',{x:x0+w/2,y:y0+fs+2,'text-anchor':'middle','font-size':fs+1,'font-weight':'700',fill:state.textColor},`${feature.label}${state.showUnit&&feature.unit?` (${state.scaleMode==='z'?'Z-score':feature.unit})`:''}`));
  const ticks=niceTicks(lo,hi,state.tickCount);for(const t of ticks){const yy=y(t);if(state.showGrid)root.append(svgEl('line',{x1:x0+left,y1:yy,x2:x0+w-right,y2:yy,stroke:'#d9dfe2','stroke-width':.55}));root.append(svgEl('line',{x1:x0+left-3,y1:yy,x2:x0+left,y2:yy,stroke:state.textColor,'stroke-width':state.axisWidth}));root.append(svgEl('text',{x:x0+left-5,y:yy+fs*.34,'text-anchor':'end','font-size':fs*.83,fill:state.textColor},fmt(t)))}
  root.append(svgEl('line',{x1:x0+left,y1:y0+top,x2:x0+left,y2:y0+top+plotH,stroke:state.textColor,'stroke-width':state.axisWidth}));root.append(svgEl('line',{x1:x0+left,y1:y0+top+plotH,x2:x0+w-right,y2:y0+top+plotH,stroke:state.textColor,'stroke-width':state.axisWidth}));
  groups.forEach((g,i)=>{const xx=x(i),color=state.colors[g.c],q1=quantile(g.a,.25),med=quantile(g.a,.5),q3=quantile(g.a,.75),[wl,wh]=whiskers(g.a);if(state.plotMode==='violin-box-points'){const ys=Array.from({length:48},(_,j)=>lo+(hi-lo)*j/47),ds=kde(g.a,ys,state.bandwidth),mx=Math.max(...ds),half=state.violinWidth*plotW/classes.length/2,path=[];ys.forEach((v,j)=>path.push(`${j?'L':'M'} ${xx-ds[j]/mx*half} ${y(v)}`));for(let j=ys.length-1;j>=0;j--)path.push(`L ${xx+ds[j]/mx*half} ${y(ys[j])}`);path.push('Z');root.append(svgEl('path',{d:path.join(' '),fill:color,'fill-opacity':.16,stroke:color,'stroke-width':.7}))}
    if(state.plotMode.includes('points')){rows.filter(r=>r.E_class===g.c).forEach(r=>{const key=state.scaleMode==='z'?`z__${feature.key}`:feature.key,m=state.scaleMode==='z'?1:feature.mult,v=Number(r[key])*m;if(Number.isFinite(v))root.append(svgEl('circle',{cx:xx+(hash(r.cell_label+feature.key)-.5)*2*state.jitter*plotW/classes.length,cy:y(v),r:state.pointSize,fill:color,'fill-opacity':state.pointOpacity,stroke:'#ffffff','stroke-width':.22}))})}
    if(state.plotMode==='violin-box-points'||state.plotMode==='box-points'){const bw=state.boxWidth*plotW/classes.length;root.append(svgEl('line',{x1:xx,y1:y(wl),x2:xx,y2:y(wh),stroke:'#29343a','stroke-width':.75}));root.append(svgEl('line',{x1:xx-bw*.25,y1:y(wl),x2:xx+bw*.25,y2:y(wl),stroke:'#29343a','stroke-width':.75}));root.append(svgEl('line',{x1:xx-bw*.25,y1:y(wh),x2:xx+bw*.25,y2:y(wh),stroke:'#29343a','stroke-width':.75}));root.append(svgEl('rect',{x:xx-bw/2,y:y(q3),width:bw,height:Math.max(.5,y(q1)-y(q3)),fill:'#ffffff','fill-opacity':.72,stroke:'#29343a','stroke-width':.8}));root.append(svgEl('line',{x1:xx-bw/2,y1:y(med),x2:xx+bw/2,y2:y(med),stroke:'#111','stroke-width':1}))}
    if(state.plotMode==='mean-ci'){const m=mean(g.a),ci=1.96*sd(g.a)/Math.sqrt(g.a.length);root.append(svgEl('line',{x1:xx,y1:y(m-ci),x2:xx,y2:y(m+ci),stroke:color,'stroke-width':2}));root.append(svgEl('line',{x1:xx-5,y1:y(m-ci),x2:xx+5,y2:y(m-ci),stroke:color,'stroke-width':2}));root.append(svgEl('line',{x1:xx-5,y1:y(m+ci),x2:xx+5,y2:y(m+ci),stroke:color,'stroke-width':2}));root.append(svgEl('circle',{cx:xx,cy:y(m),r:3.2,fill:color,stroke:'#fff','stroke-width':.6}))}
    root.append(svgEl('text',{x:xx,y:y0+top+plotH+fs+6,'text-anchor':'middle','font-size':fs,fill:state.textColor},state.showN?`${g.c} (${g.a.length})`:g.c))});
  if(state.statMode==='omnibus'){const r=omnibus.get(feature.key),q=r?.Q_BH_across_19_features;root.append(svgEl('text',{x:x0+w-right,y:y0+top-7,'text-anchor':'end','font-size':fs*.82,fill:'#5a6870'},`Kruskal–Wallis q=${pFmt(q)}`))}
  sigPairs.forEach((r,i)=>{const a=classes.indexOf(r.Group_1),b=classes.indexOf(r.Group_2);if(a<0||b<0)return;const yy=y0+top-7-i*9,xa=x(a),xb=x(b);root.append(svgEl('path',{d:`M${xa},${yy+3}V${yy}H${xb}V${yy+3}`,fill:'none',stroke:'#3d464b','stroke-width':.7}));root.append(svgEl('text',{x:(xa+xb)/2,y:yy-1,'text-anchor':'middle','font-size':fs*.72,fill:state.textColor},pFmt(r.P_adj_Holm_within_feature)))})
}
function render(){if(!rows.length)return;const selected=state.featureOrder.filter(k=>state.selected.includes(k)).map(k=>FEATURES.find(f=>f.key===k)),classes=CLASSES.filter(c=>state.activeClasses[c]);$('featureCount').textContent=`${selected.length} / 19`;$('selectionSummary').textContent=`${selected.length} features · ${classes.join(', ')} · ${state.scaleMode==='z'?'frozen Z-score':'raw scale'}`;if(!selected.length||!classes.length){$('preview').innerHTML='<div style="padding:40px;background:white">请至少选择一个特征和一个组别。</div>';return}const cols=Math.min(state.columns,selected.length),rowsN=Math.ceil(selected.length/cols),titleH=state.figureTitle?34:10,legendH=state.showLegend?24:0,width=cols*state.panelWidth+(cols-1)*state.gapX+24,height=titleH+rowsN*state.panelHeight+(rowsN-1)*state.gapY+legendH+14;const svg=svgEl('svg',{xmlns:NS,width,height,viewBox:`0 0 ${width} ${height}`,'data-export-width':width,'data-export-height':height,style:`font-family:${state.fontFamily};background:${state.backgroundColor}`});svg.append(svgEl('rect',{width:'100%',height:'100%',fill:state.backgroundColor}));if(state.figureTitle)svg.append(svgEl('text',{x:width/2,y:22,'text-anchor':'middle','font-size':state.fontSize+4,'font-weight':'700',fill:state.textColor},state.figureTitle));selected.forEach((f,i)=>drawPanel(svg,f,12+(i%cols)*(state.panelWidth+state.gapX),titleH+Math.floor(i/cols)*(state.panelHeight+state.gapY),state.panelWidth,state.panelHeight,classes));if(state.showLegend){let lx=12,ly=height-10;classes.forEach(c=>{svg.append(svgEl('circle',{cx:lx+4,cy:ly-3,r:4,fill:state.colors[c]}));svg.append(svgEl('text',{x:lx+12,y:ly,'font-size':state.fontSize,fill:state.textColor},c));lx+=45})}$('preview').replaceChildren(svg);$('preview').style.transform=`scale(${state.previewZoom/100})`;$('preview').parentElement.style.setProperty('--dummy','1');$('canvasReadout').textContent=`${width} × ${height} px`}

function makeFeatureList(){const box=$('featureList');box.innerHTML='';state.featureOrder.forEach((key,i)=>{const f=FEATURES.find(x=>x.key===key),row=document.createElement('div');row.className='feature-row';row.innerHTML=`<input type="checkbox" ${state.selected.includes(key)?'checked':''} aria-label="选择 ${f.label}"><label title="${f.key}">${f.label}</label><button title="上移" aria-label="上移 ${f.label}">↑</button><button title="下移" aria-label="下移 ${f.label}">↓</button>`;row.children[0].onchange=e=>{state.selected=e.target.checked?[...state.selected,key]:state.selected.filter(x=>x!==key);render();$('featureCount').textContent=`${state.selected.length} / 19`};row.children[2].onclick=()=>moveFeature(i,-1);row.children[3].onclick=()=>moveFeature(i,1);box.append(row)})}
function moveFeature(i,d){const j=i+d;if(j<0||j>=state.featureOrder.length)return;[state.featureOrder[i],state.featureOrder[j]]=[state.featureOrder[j],state.featureOrder[i]];makeFeatureList();render()}
function makeClassControls(){const box=$('classControls');box.innerHTML='';CLASSES.forEach(c=>{const d=document.createElement('div');d.className='class-chip';d.innerHTML=`<input type="checkbox" ${state.activeClasses[c]?'checked':''}><label>${c}</label><input type="color" value="${state.colors[c]}" aria-label="${c} 颜色">`;d.children[0].onchange=e=>{state.activeClasses[c]=e.target.checked;render()};d.children[2].oninput=e=>{state.colors[c]=e.target.value;render()};box.append(d)})}
const bindings={scaleMode:'value',plotMode:'value',statMode:'value',pairCount:'number',showN:'checked',showLegend:'checked',pointSize:'number',pointOpacity:'number',jitter:'number',violinWidth:'number',bandwidth:'number',boxWidth:'number',whiskerMode:'value',fontFamily:'value',fontSize:'number',axisWidth:'number',tickCount:'number',showGrid:'checked',showUnit:'checked',figureTitle:'value',columns:'number',panelWidth:'number',panelHeight:'number',gapX:'number',gapY:'number',previewZoom:'number',pngScale:'number',backgroundColor:'value',textColor:'value'};
function bindControls(){for(const[id,type]of Object.entries(bindings)){const el=$(id);el.addEventListener(type==='value'?'change':'input',()=>{state[id]=type==='checked'?el.checked:type==='number'?Number(el.value):el.value;syncOutputs();render()})}$('allFeatures').onclick=()=>{state.selected=[...state.featureOrder];makeFeatureList();render()};$('top10Features').onclick=()=>{state.selected=state.featureOrder.slice(0,10);makeFeatureList();render()};$('clearFeatures').onclick=()=>{state.selected=[];makeFeatureList();render()};$('resetBtn').onclick=()=>{state=structuredClone(DEFAULTS);syncControls();makeFeatureList();makeClassControls();render();toast('已恢复默认参数')};$('exportSvgBtn').onclick=exportSVG;$('exportPngBtn').onclick=exportPNG;$('savePreset').onclick=savePreset;$('loadPreset').onclick=()=>$('presetFile').click();$('presetFile').onchange=loadPreset}
function syncOutputs(){for(const id of ['pairCount','pointSize','pointOpacity','jitter','violinWidth','bandwidth','fontSize','axisWidth','tickCount','columns'])$(`${id}Out`).textContent=state[id];for(const id of ['panelWidth','panelHeight','gapX','gapY'])$(`${id}Out`).textContent=`${state[id]} px`;$('previewZoomOut').textContent=`${state.previewZoom}%`;$('pairCountWrap').hidden=state.statMode!=='pairwise'}
function syncControls(){for(const[id,type]of Object.entries(bindings)){const el=$(id);if(type==='checked')el.checked=state[id];else el.value=state[id]}syncOutputs()}
function currentSVG(){const svg=$('preview').querySelector('svg');if(!svg)throw Error('No figure');const clone=svg.cloneNode(true);clone.setAttribute('xmlns',NS);return new XMLSerializer().serializeToString(clone)}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportSVG(){download(new Blob([currentSVG()],{type:'image/svg+xml;charset=utf-8'}),'Macaque_E1-E4_feature_comparison.svg');toast('SVG 已按当前预览导出')}
function exportPNG(){const svg=$('preview').querySelector('svg'),scale=Number(state.pngScale),w=Number(svg.dataset.exportWidth),h=Number(svg.dataset.exportHeight),img=new Image(),url=URL.createObjectURL(new Blob([currentSVG()],{type:'image/svg+xml'}));img.onload=()=>{const c=document.createElement('canvas');c.width=w*scale;c.height=h*scale;const ctx=c.getContext('2d');ctx.scale(scale,scale);ctx.drawImage(img,0,0,w,h);URL.revokeObjectURL(url);c.toBlob(b=>download(b,'Macaque_E1-E4_feature_comparison.png'),'image/png');toast(`PNG 已按当前预览以 ${scale}× 导出`)};img.src=url}
function savePreset(){download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'Macaque_E4_figure_preset.json');toast('绘图参数已导出')}
function loadPreset(e){const f=e.target.files[0];if(!f)return;const r=new FileReader();r.onload=()=>{try{state={...structuredClone(DEFAULTS),...JSON.parse(r.result)};syncControls();makeFeatureList();makeClassControls();render();toast('参数已载入')}catch{toast('参数文件无法读取')}};r.readAsText(f);e.target.value=''}
let toastTimer;function toast(s){$('toast').textContent=s;$('toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('show'),1800)}
function registerWebMCP(){const mc=document.modelContext;if(!mc?.registerTool)return;mc.registerTool({name:'configure_feature_figure',title:'Configure E-feature figure',description:'Update the visible Macaque E1–E4 feature comparison using the same settings as the editor controls.',inputSchema:{type:'object',properties:{features:{type:'array',items:{type:'string'},description:'Feature keys to display'},scaleMode:{enum:['raw','z']},plotMode:{enum:['violin-box-points','box-points','points','mean-ci']},columns:{type:'integer',minimum:1,maximum:5}},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(input.features){const valid=input.features.filter(k=>FEATURES.some(f=>f.key===k));if(!valid.length)throw Error('No valid features');state.selected=valid}if(input.scaleMode)state.scaleMode=input.scaleMode;if(input.plotMode)state.plotMode=input.plotMode;if(input.columns)state.columns=input.columns;syncControls();makeFeatureList();render();return{features:state.selected.length,scaleMode:state.scaleMode,plotMode:state.plotMode,columns:state.columns}}})}
syncControls();makeFeatureList();makeClassControls();bindControls();loadData().then(registerWebMCP).catch(e=>{$('dataStatus').textContent='数据载入失败，请通过本地预览或部署链接打开。';console.error(e)});
